function pb.learn(zq)
local Aq={}
for Bq in pairs(zq.ids or{})do
local Cq,Dq=pcall(pb.guess,Bq)
for Eq,Fq in ipairs(Cq and type(Dq)==mee[1954]and Dq or{})do
if Fq.playable and not Fq.hand then
local Gq,Hq=pcall(pb.evidence,zq,Bq,Fq)
