local Iq=type(P.pasBook[Bq])==mee[1954]and P.pasBook[Bq]or{}
local Jq=type(Iq[Fq.pid])==mee[1954]and Iq[Fq.pid]or nil
local Kq={}
for Lq,Mq in pairs(Fq.nums or{})do
