for Nq,Oq in pairs(Hq.nums or{})do
Kq[Nq]=Oq
end
local Pq=Jq~=nil and Jq.family==Fq.family and(Jq.buff==nil or Hq.buff==nil or Jq.buff==Hq.buff)
Iq[Fq.pid]={family=Fq.family,name=Fq.name,nums=Kq,buff=Hq.buff or(Jq and Jq.buff),who=Hq.who or Fq.who,trigger=Fq.trigger,keyword=Fq.keyword,sure=(Pq and(tonumber(Jq.runs)or 0)>=1)and mee[2316]or mee[2376],runs=(Pq and(tonumber(Jq.runs)or 0)or 0)+1,at=os.time(),why=Hq.why}
P.pasBook[Bq]=Iq
table.insert(Aq,{id=Bq,g=Fq,e=Iq[Fq.pid]})
elseif Gq and type(Hq)==mee[1954]then
table.insert(Aq,{id=Bq,g=Fq,miss=Hq.why})
else
table.insert(Aq,{id=Bq,g=Fq,miss=mee[2377]..tostring(Hq)})
end
end
end
end
pb._model={}
return Aq
end
