if type(Agc)~=mee[1954]or type(Agc.uuids)~=mee[1954]or Agc.seed~=tostring(zgc.r._r)then
return nil
end
if os.time()-(tonumber(Agc.at)or 0)>3600 then
P.dg.force=nil
return nil
end
return Agc
end
function jb.startTeam(Bgc,Cgc,Dgc,Egc)
