F.log(1,mee[3590],string.format(mee[3907],Fgc.d,V.name(Whc.unit_id),V.bleeds(Whc.unit_id)or 0,table.concat(Xhc,mee[2329])))
jb.bleedTried=string.format(mee[3908],V.name(Whc.unit_id),V.bleeds(Whc.unit_id)or 0,table.concat(Xhc,mee[2329]))
