for Jic,Kic in ipairs(V.equipped())do
table.insert(Iic,V.name(Kic.id))
end
if Dic+1>=2 and Bic and Bic.better and Bic.seed==Cic then
Bic.better=false
F.log(1,mee[2966],string.format(mee[3933],vic.d))
pcall(ab.restoreTeam)
end
F.log(1,mee[3844],string.format(mee[3934],vic.d,#Gic,table.concat(Iic,mee[2066])))
F.status(mee[2984],mee[3935]..vic.d)
