if(not Nic or Oic>=2 or Pic)and not(jb.playLast()and not Pic)then
local Qic=Pic and string.format(mee[3936],#V.equipped())or Oic>=2 and string.format(mee[3937],Oic)or mee[3938]
jb.note(string.format(mee[3939],vic.d,Qic))
W.rec(mee[2665]).restUntil=os.time()+3600
P.pending=nil
