P.dg.room={seed=vic.r._r,d=vic.d}
P.pending={key=mee[2665],kind=mee[1974],level=mee[1974],diff=mee[2449],label=mee[3940]..vic.d,at=os.time(),value=qic,depth=vic.d}
if P.nextMode==mee[2665]then
P.nextMode=nil
end
local Ric,Sic,Tic=jb.res(pic)
local Uic=string.format(mee[3941],math.floor(vic.p*100+0.5),vic.sim and(mee[3942]..tostring(vic.sim.margin)..mee[2608])or mee[877],vic.nextRoom and jb.roomName(vic.nextRoom)or mee[3943],jb.lives(pic),Ric,Sic,Tic)
