jb.WAY_WORDS={fast=mee[3955],balanced=mee[3738],box=mee[3633]}
function jb.ways(ijc)
local function jjc(kjc,ljc,mjc)
local njc=table.clone(ijc)
njc.zone,njc.placeAll=ljc,mjc
return{style=kjc,info=njc}
end
local ojc=bb.forcedWay()
if ojc then
return{jjc(ojc,ojc==mee[3608],ojc==mee[3609]and mee[3354]or nil)}
end
local pjc={jjc(mee[3609],false,mee[3354]),jjc(mee[3647],false,nil)}
if O.killZone~=false then
table.insert(pjc,jjc(mee[3608],true,nil))
end
return pjc
end
jb.ROOM_K_MAX=6
function jb.roomK(qjc)
local rjc=qjc~=nil and type(P.dg.roomK)==mee[1954]and P.dg.roomK[tostring(qjc)]or nil
return type(rjc)==mee[1954]and tonumber(rjc.k)or 1
end
function jb.applyK(sjc,tjc)
local ujc=jb.roomK(tjc)
if sjc and ujc>1 then
sjc.hpScale=(tonumber(sjc.hpScale)or 1)*ujc
sjc.roomK=ujc
end
return ujc
end
function jb.roomLearn(vjc)
if vjc or bb.kind~=mee[1974]or bb.roomLearned then
return
end
local wjc=P.dg.room
local xjc,yjc=bb.pred,bb.calRun
if type(wjc)~=mee[1954]or wjc.seed==nil or type(xjc)~=mee[1954]or not xjc.won or type(yjc)~=mee[1954]then
return
end
local function zjc(Ajc,Bjc)
return type(Ajc)==mee[1954]and tonumber(Ajc[Bjc]or Ajc[tostring(Bjc)])or nil
end
local Cjc={}
for Djc=2,bb.wave()do
local Ejc,Fjc=zjc(yjc.alive,Djc),zjc(xjc.aliveAt,Djc)
if Ejc and Fjc and Ejc>0 and Fjc>0 then
table.insert(Cjc,Ejc/Fjc)
end
end
if#Cjc<3 then
return
end
table.sort(Cjc)
local Gjc=Cjc[math.ceil(#Cjc/2)]
bb.roomLearned=true
if Gjc<=1.05 then
return
end
P.dg.roomK=type(P.dg.roomK)==mee[1954]and P.dg.roomK or{}
local Hjc=tostring(wjc.seed)
local Ijc=P.dg.roomK[Hjc]
local Jjc=math.min(jb.ROOM_K_MAX,jb.roomK(Hjc)*Gjc)
P.dg.roomK[Hjc]={k=Jjc,n=(type(Ijc)==mee[1954]and tonumber(Ijc.n)or 0)+1,at=os.time(),d=wjc.d}
bb.roomKUp=true
local Kjc={}
for Ljc,Mjc in pairs(P.dg.roomK)do
table.insert(Kjc,{s=Ljc,at=type(Mjc)==mee[1954]and tonumber(Mjc.at)or 0})
end
table.sort(Kjc,function(Njc,Ojc)
return Njc.at>Ojc.at
end)
for Pjc=31,#Kjc do
P.dg.roomK[Kjc[Pjc].s]=nil
end
F.log(1,mee[3844],string.format(mee[3956],tostring(wjc.d),Gjc,Jjc))
end
function jb.roomDone(Qjc)
pcall(jb.roomLearn,Qjc)
if type(P.simTeam)==mee[1954]and type(P.simTeam.dg)==mee[1954]then
P.simTeam.dg.stale=true
end
P.dg.playLast=nil
local Rjc=tonumber(type(bb.ld._dungeon)==mee[1954]and bb.ld._dungeon.depth)or(P.pending and tonumber(P.pending.depth))or 1
local Sjc=tostring(math.min(4,math.max(1,math.ceil(Rjc/5))))
local Tjc=P.dg.depth[Sjc]or{runs=0,wins=0}
Tjc.runs,Tjc.wins=(tonumber(Tjc.runs)or 0)+1,(tonumber(Tjc.wins)or 0)+(Qjc and 1 or 0)
P.dg.depth[Sjc]=Tjc
local Ujc=jb.data()
local Vjc,Wjc,Xjc=jb.res(Ujc)
jb.note(string.format(mee[3957],Rjc,jb.ROOMS,Qjc and mee[3958]or mee[2691],Vjc,Wjc,Xjc,jb.lives(Ujc)))
P.dg.teams=type(P.dg.teams)==mee[1954]and P.dg.teams or{}
local Yjc=P.dg.teams[W.teamSig()]or{w=0,l=0}
if Qjc then
Yjc.w=(tonumber(Yjc.w)or 0)+1
else
Yjc.l=(tonumber(Yjc.l)or 0)+1
end
P.dg.teams[W.teamSig()]=Yjc
if Qjc then
P.dg.lives=5
elseif P.dg.room and P.dg.room.d==Rjc then
P.dg.lost=P.dg.lost or{}
local Zjc,_jc=tostring(P.dg.room.seed),W.teamSig()
P.dg.lost[Zjc]=P.dg.lost[Zjc]or{}
P.dg.lost[Zjc][_jc]=(P.dg.lost[Zjc][_jc]or 0)+1
end
end
function jb.text()
