function bb.buildPath()
bb.samples={}
local qkc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not qkc then
return
end
for rkc,skc in pairs(qkc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[rkc.Name])then
local tkc={}
for ukc,vkc in ipairs(skc.points or{})do
table.insert(tkc,vkc.part.Position)
end
local wkc=0
for xkc=2,#tkc do
wkc=wkc+(tkc[xkc]-tkc[xkc-1]).Magnitude
end
local ykc=0
for zkc=2,#tkc do
local Akc,Bkc=tkc[zkc-1],tkc[zkc]
local Ckc=(Bkc-Akc).Magnitude
local Dkc=math.max(1,math.floor(Ckc/2))
for Ekc=0,Dkc-1 do
local Fkc=Akc:Lerp(Bkc,Ekc/Dkc)
table.insert(bb.samples,{pos=Fkc,prog=(ykc+Ckc*Ekc/Dkc)/math.max(1,wkc),lane=rkc.Name})
end
ykc=ykc+Ckc
end
if tkc[#tkc]then
table.insert(bb.samples,{pos=tkc[#tkc],prog=1,lane=rkc.Name})
end
end
end
pcall(bb.readHidden,qkc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local Gkc=tonumber(bb.ld and bb.ld._portal_lanes)
local Hkc=gb.laneList(bb.samples)
if Gkc and Gkc>=1 and Hkc and#Hkc>Gkc then
bb.laneWant=Gkc
end
bb.laneTotal=Hkc and#Hkc or 1
bb.countLanes()
end
function bb.readHidden(Ikc)
local Jkc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(Jkc)~=mee[1954]or not next(Jkc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local Kkc
for Lkc,Mkc in pairs(Ikc)do
if Jkc[Lkc.Name]and type(Mkc.points)==mee[1954]and#Mkc.points>=2 then
local Nkc={}
for Okc,Pkc in ipairs(Mkc.points)do
Nkc[Okc]=U.flat(Pkc.part.Position)
end
local Qkc={}
for Rkc,Skc in ipairs(bb.samples)do
local Tkc=tostring(Skc.lane)
Qkc[Tkc]=Qkc[Tkc]or{}
table.insert(Qkc[Tkc],Skc)
end
local Ukc,Vkc
for Wkc,Xkc in pairs(Qkc)do
local Ykc=0
for Zkc=1,#Nkc,math.max(1,math.floor(#Nkc/20))do
local _kc=math.huge
for alc,blc in ipairs(Xkc)do
local clc=(U.flat(blc.pos)-Nkc[Zkc]).Magnitude
if clc<_kc then
_kc=clc
end
end
Ykc=Ykc+_kc
end
if not Vkc or Ykc<Vkc then
Ukc,Vkc=Wkc,Ykc
end
end
local dlc,elc,flc,glc,hlc,ilc={},nil,nil,nil,0,0
for jlc,klc in ipairs(Nkc)do
local llc,mlc=nil,math.huge
for nlc,olc in ipairs(Qkc[Ukc])do
local plc=(U.flat(olc.pos)-klc).Magnitude
if plc<mlc then
mlc,llc=plc,olc.prog
end
end
ilc=math.max(ilc,mlc)
if flc then
local qlc=llc-flc
local rlc=(qlc>0.002 and 1)or(qlc< -0.002 and-1)or glc
if glc and rlc and rlc~=glc then
table.insert(dlc,math.floor(flc*1000+0.5)/1000)
end
glc,hlc=rlc or glc,hlc+math.abs(qlc)
else
elc=llc
end
flc=llc
if jlc%50==0 then
task.wait()
end
end
if flc and ilc<=8 then
table.insert(dlc,math.floor(flc*1000+0.5)/1000)
Kkc=Kkc or{}
Kkc[Lkc.Name]={from=math.floor((elc or 0)*1000+0.5)/1000,len=math.floor(hlc*1000+0.5)/1000,turns=dlc,road=Ukc}
end
end
end
if not Kkc then
return
end
local slc=bb.ld.map
P.maps[slc]=P.maps[slc]or{}
local tlc=P.maps[slc].hidden
P.maps[slc].hidden=Kkc
if type(tlc)~=mee[1954]then
for ulc,vlc in pairs(Kkc)do
F.log(1,mee[2615],string.format(mee[3972],ulc,vlc.len,tostring(vlc.road),math.floor((#vlc.turns-1)/2)))
end
F.saveSoon()
end
end
function bb.countLanes()
