if Jlc and Jlc:FindFirstChild(mee[3973])and Jlc.player.Value==nil and Jlc:FindFirstChild(mee[3974])and Ilc:FindFirstChild(mee[3174])then
local Klc=tostring(Jlc.lane.Value)
if not Flc[Klc]then
Flc[Klc]=true
Glc=Glc+1
