local tmc
for umc,vmc in ipairs(smc and W.lastScored or{})do
if vmc.kind~=mee[1973]and(not tmc or(vmc.score or 0)>(tmc.score or 0))then
tmc=vmc
end
end
if not tmc or(tmc.score or 0)<=omc then
