function bb.studyMoves(kDc,lDc)
local mDc=V.rows(kDc.id)
local nDc=V.range(kDc.e.u,mDc.max)*lDc
local oDc=nDc*nDc
local pDc,qDc={},{}
local rDc,sDc=bb.hurtSamples(),bb.sandLine()
for tDc,uDc in ipairs(kDc.spots or{})do
local vDc,wDc,xDc,yDc,zDc=0,0,0,0,0
for ADc,BDc in ipairs(rDc)do
local CDc,DDc=BDc.pos.X-uDc.X,BDc.pos.Z-uDc.Z
if CDc*CDc+DDc*DDc<=oDc then
xDc=xDc+1
local EDc=math.min(49,math.floor(BDc.prog*50))
if EDc<25 then
vDc=bit32 .bor(vDc,bit32 .lshift(1,EDc))
else
wDc=bit32 .bor(wDc,bit32 .lshift(1,EDc-25))
end
if BDc.prog-sDc<=0.3 then
yDc=yDc+1
elseif BDc.prog>=0.7 then
zDc=zDc+1
end
end
end
if xDc>0 then
local FDc=vDc..mee[2089]..wDc
local GDc=pDc[FDc]
if not GDc then
GDc={p=uDc,lo=vDc,hi=wDc,n=xDc,early=yDc,late=zDc}
pDc[FDc]=GDc
table.insert(qDc,GDc)
elseif xDc>GDc.n then
GDc.p,GDc.n,GDc.early,GDc.late=uDc,xDc,yDc,zDc
end
end
if tDc%40==0 then
task.wait()
end
end
local HDc={}
for IDc,JDc in ipairs(qDc)do
local KDc=false
for LDc,MDc in ipairs(qDc)do
if IDc~=LDc and MDc.n>=JDc.n and bit32 .band(JDc.lo,MDc.lo)==JDc.lo and bit32 .band(JDc.hi,MDc.hi)==JDc.hi and(MDc.lo~=JDc.lo or MDc.hi~=JDc.hi or MDc.n>JDc.n)then
KDc=true
break
end
end
if not KDc then
table.insert(HDc,JDc)
end
if IDc%40==0 then
task.wait()
end
end
local NDc,ODc={},{}
local function PDc(QDc)
if QDc and not ODc[QDc]then
ODc[QDc]=true
table.insert(NDc,QDc)
end
end
table.sort(HDc,function(RDc,SDc)
return RDc.n>SDc.n
end)
for TDc=1,math.min(bb.STUDY_K,#HDc)do
PDc(HDc[TDc].p)
end
table.sort(HDc,function(UDc,VDc)
return UDc.early>VDc.early
end)
PDc(HDc[1]and HDc[1].p)
PDc(HDc[2]and HDc[2].p)
table.sort(HDc,function(WDc,XDc)
return WDc.late>XDc.late
end)
PDc(HDc[1]and HDc[1].p)
PDc(HDc[2]and HDc[2].p)
local YDc=0
for ZDc,_Dc in ipairs(bb.hiveSpots(bb.ld and bb.ld.map))do
if YDc>=bb.STUDY_SHARED then
break
end
local aEc=false
for bEc,cEc in ipairs(type(_Dc.units)==mee[1954]and _Dc.units or{})do
local dEc=cEc==kDc.id and nDc or((bb.baseRange(cEc)or 0)*lDc)
if cEc==kDc.id or(dEc>0 and math.abs(dEc-nDc)<=0.3*nDc)then
aEc=true
break
end
end
local eEc=aEc and tonumber(_Dc.x)and tonumber(_Dc.z)and bb.nearSpot(kDc.spots,tonumber(_Dc.x),tonumber(_Dc.z))or nil
if eEc and not ODc[eEc]then
PDc(eEc)
YDc=YDc+1
end
end
return NDc,#qDc,#HDc,YDc
end
function bb.studyRun(fEc)
local gEc=U.now()
while F.alive and not(bb.finished or bb.result)and(bb.planning or U.now()-gEc<20)do
