end
local function hEc()
return F.alive and not(bb.finished or bb.result)and O.mapStudy~=false and F.where==mee[2026]
end
if not hEc()then
return
end
local iEc,jEc,kEc=fEc.info,fEc.team,fEc.base
local lEc=iEc.timeLimit~=nil
local mEc=lEc and 1 or math.max(1,tonumber(fEc.hard)or 1)
local nEc={mEc*0.95,mEc*1.05}
local oEc=bb.bookFor(iEc)
local pEc={key=fEc.key,label=bb.label(),n=oEc and tonumber(oEc.n)or 0,run=0,timed=lEc,kills=iEc.killScore and true or nil,hp=mEc,at=os.time()}
bb.study=pEc
