table.insert(sFc,vFc[HFc])
end
end
local IFc={}
for JFc,KFc in ipairs(fEc.attackers)do
if qEc[KFc.id]and#qEc[KFc.id]>0 then
table.insert(IFc,KFc.id)
end
end
while hEc()and#IFc>0 do
local LFc=TEc(dFc.spots)
for MFc=1,math.min(2,#IFc)do
local NFc=IFc[math.random(#IFc)]
local OFc=qEc[NFc]
local PFc=OFc[math.random(#OFc)]
if not YEc(LFc,NFc,PFc)then
LFc[NFc]=PFc
end
end
local QFc,RFc,SFc=KEc(LFc)
if not QFc then
break
end
pFc({spots=LFc,s=QFc,kills=RFc,wave=SFc})
rFc()
end
bb.studyEnd(pEc,fEc,dFc)
end
