function bb.validOpen(TFc,UFc)
local VFc=N.PC.raycast(TFc+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not VFc then
return nil
end
if not N.PC.is_valid_raycast_hit(VFc.Instance,UFc)then
return nil
end
local WFc=VFc.Position
