return nil
end
local XFc=(tonumber(UFc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(XFc*2,2.5,XFc*2)
bb.probe.CFrame=CFrame.new(WFc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
return WFc
end
