function nb.K.key(LMd,MMd)
local NMd,OMd,PMd=nb.K,nb.Win,Enum.KeyCode
if NMd.cur and not(NMd.cur.obj and NMd.cur.obj.Parent and NMd.shown(NMd.cur.obj))then
NMd.setFocus(nil)
end
if NMd.cur and NMd.cur.listKey and NMd.cur.listKey(LMd)then
return true
end
if LMd==PMd.PageUp or LMd==PMd.PageDown then
local QMd={}
for RMd,SMd in pairs(OMd._tabs)do
table.insert(QMd,{name=RMd,y=SMd.btn.AbsolutePosition.Y,on=SMd.page.Visible})
end
table.sort(QMd,function(TMd,UMd)
return TMd.y<UMd.y
end)
local VMd=1
for WMd,XMd in ipairs(QMd)do
if XMd.on then
VMd=WMd
end
end
VMd=(VMd-1+(LMd==PMd.PageDown and 1 or-1))% #QMd+1
NMd.setFocus(nil)
OMd:SelectTab(QMd[VMd].name)
return true
end
if LMd==PMd.Tab or LMd==PMd.Down or LMd==PMd.Up then
local YMd=NMd.order()
if#YMd==0 then
return true
end
local ZMd=LMd==PMd.Up or(LMd==PMd.Tab and MMd)
local _Md=table.find(YMd,NMd.cur)
if not _Md then
_Md=ZMd and#YMd or 1
else
_Md=(_Md-1+(ZMd and-1 or 1))% #YMd+1
end
NMd.setFocus(YMd[_Md])
return true
end
if not NMd.cur then
return false
end
if LMd==PMd.Return or LMd==PMd.KeypadEnter or LMd==PMd.Space then
if NMd.cur.activate then
NMd.cur.activate()
end
return true
end
if LMd==PMd.Left or LMd==PMd.Right then
if NMd.cur.adjust then
NMd.cur.adjust(LMd==PMd.Right and 1 or-1)
end
return true
end
if LMd==PMd.Escape then
NMd.setFocus(nil)
return true
end
return false
end
function nb.K.keys(aNd)
local bNd=nb.K
local cNd,dNd,eNd=game:GetService(mee[5193]),game:GetService(mee[5117]),game:GetService(mee[5194])
