bNd.keyName=mee[5195]..(tostring(nb.TITLE):gsub(mee[5196],mee[877]))
function bNd.over()
local gNd=aNd._main
if not(gNd and gNd.Parent and gNd.Visible)then
return false
end
local hNd=dNd:GetMouseLocation()
local iNd=eNd:GetGuiInset()
local jNd,kNd=hNd.X,hNd.Y-iNd.Y
local lNd,mNd=gNd.AbsolutePosition,gNd.AbsoluteSize
return jNd>=lNd.X and jNd<=lNd.X+mNd.X and kNd>=lNd.Y and kNd<=lNd.Y+mNd.Y
end
cNd:BindActionAtPriority(bNd.keyName,function(nNd,oNd,pNd)
if oNd~=Enum.UserInputState.Begin then
return Enum.ContextActionResult.Pass
end
if dNd:GetFocusedTextBox()or not bNd.over()then
return Enum.ContextActionResult.Pass
end
local qNd,rNd=pcall(bNd.key,pNd.KeyCode,dNd:IsKeyDown(fNd.LeftShift)or dNd:IsKeyDown(fNd.RightShift))
return(qNd and rNd)and Enum.ContextActionResult.Sink or Enum.ContextActionResult.Pass
end,false,3000,fNd.Tab,fNd.Return,fNd.KeypadEnter,fNd.Space,fNd.Left,fNd.Right,fNd.Up,fNd.Down,fNd.Escape,fNd.PageUp,fNd.PageDown)
aNd._track(dNd.InputBegan:Connect(function(sNd)
if sNd.UserInputType==Enum.UserInputType.MouseButton1 and bNd.cur then
pcall(bNd.setFocus,nil)
end
end))
aNd._screen.Destroying:Connect(function()
pcall(function()
cNd:UnbindAction(bNd.keyName)
